using System;
using System.IO;
using System.IO.Compression;
using System.Diagnostics;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
using System.Drawing;
using System.Web.Script.Serialization;
using Microsoft.Win32;
class Setup:Form {
 Label title=new Label(),status=new Label();ProgressBar bar=new ProgressBar();string[] args;bool running=true;static JavaScriptSerializer json=new JavaScriptSerializer();
 Setup(string[] a){args=a;Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);Text="灵搭 Sparkit · 安装与原路径更新";Width=620;Height=235;StartPosition=FormStartPosition.CenterScreen;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;Font=new Font("Microsoft YaHei",10);BackColor=SetupTheme.Surface;ForeColor=SetupTheme.Ink;status.ForeColor=SetupTheme.Muted;bar.ForeColor=SetupTheme.Accent;title.SetBounds(24,20,560,32);title.Text="正在准备 灵搭 Sparkit 安装更新";title.Font=new Font(Font,FontStyle.Bold);status.SetBounds(24,65,560,70);bar.SetBounds(24,150,560,22);bar.Style=ProgressBarStyle.Marquee;Controls.AddRange(new Control[]{title,status,bar});FormClosing+=(s,e)=>{if(running)e.Cancel=true;};Shown+=async(s,e)=>{try{await Task.Run(()=>Install());running=false;Close();}catch(Exception x){running=false;bar.Style=ProgressBarStyle.Continuous;status.Text=x.Message;title.Text="安装未完成，原版本已保留或恢复";Environment.ExitCode=1;string log=Environment.GetEnvironmentVariable("PSD_LINGO_SETUP_RESULT");if(log!=null)File.WriteAllText(log,json.Serialize(new{status="failed",error=x.Message}));if(args.Contains("--no-error-dialog"))Close();else {var close=new Button();close.Text="关闭";close.SetBounds(484,150,100,30);close.BackColor=SetupTheme.Accent;close.ForeColor=Color.White;close.FlatStyle=FlatStyle.Flat;close.Click+=(sender,evt)=>Close();bar.Visible=false;Controls.Add(close);}}};}
 void Progress(string value){Invoke((Action)(()=>{status.Text=value;}));}
 void ExtractProgress(long done,long total){Invoke((Action)(()=>{bar.Style=ProgressBarStyle.Continuous;bar.Value=total>0?(int)Math.Min(100,done*100/total):0;status.Text="正在准备新版文件 · "+bar.Value+"%";}));}
 static string Full(string p){return Path.GetFullPath(p).TrimEnd(Path.DirectorySeparatorChar);}
 static bool Same(string a,string b){return string.Equals(Full(a),Full(b),StringComparison.OrdinalIgnoreCase);}
 static bool Under(string p,string root){return Full(p).StartsWith(Full(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);}
 static string ExeOf(Process p){try{return p.MainModule.FileName;}catch{return null;}}
 static bool ValidRuntime(string folder){try{string exe=Path.Combine(folder,"PSD Lingo.exe"),manifest=Path.Combine(folder,"resources","app","package.json");if(!File.Exists(exe)||!File.Exists(manifest))return false;var m=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(manifest));return (string)m["name"]=="psd-lingo"&&(string)m["main"]=="main.cjs";}catch{return false;}}
 static string RuntimeVersion(string folder){var m=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(folder,"resources","app","package.json")));return (string)m["version"];}
 static int CompareVersion(string a,string b){string[] left=a.Split('.'),right=b.Split('.');if(left.Length!=3||right.Length!=3)throw new Exception("安装版本格式无效");for(int i=0;i<3;i++){int x,y;if(!int.TryParse(left[i],out x)||!int.TryParse(right[i],out y)||x<0||y<0)throw new Exception("安装版本格式无效");if(x!=y)return x.CompareTo(y);}return 0;}
 static bool HasDesktopShortcut(){foreach(var desktop in new[]{Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.CommonDesktopDirectory)}.Distinct(StringComparer.OrdinalIgnoreCase)){if(!Directory.Exists(desktop))continue;foreach(var file in Directory.GetFiles(desktop,"*")){string name=Path.GetFileNameWithoutExtension(file),ext=Path.GetExtension(file);if((ext.Equals(".lnk",StringComparison.OrdinalIgnoreCase)||ext.Equals(".url",StringComparison.OrdinalIgnoreCase))&&(name.Equals("灵搭 Sparkit",StringComparison.OrdinalIgnoreCase)||name.Equals("PSD Lingo",StringComparison.OrdinalIgnoreCase)||System.Text.RegularExpressions.Regex.IsMatch(name,@"^PSD Lingo \(\d+\)$",System.Text.RegularExpressions.RegexOptions.IgnoreCase)))return true;}}return false;}
 static List<Process> RunningAt(string exe){return Process.GetProcessesByName("PSD Lingo").Where(p=>{string v=ExeOf(p);return v!=null&&Same(v,exe);}).ToList();}
 string Target(){int at=Array.IndexOf(args,"--target");if(at>=0){if(at+1>=args.Length)throw new Exception("缺少目标安装目录");return Full(args[at+1]);}
 var candidates=Process.GetProcessesByName("PSD Lingo").Select(p=>ExeOf(p)).Where(p=>p!=null&&Path.GetFileName(p).Equals("PSD Lingo.exe",StringComparison.OrdinalIgnoreCase)).Select(p=>Path.GetDirectoryName(p)).Where(p=>ValidRuntime(p)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();
 if(candidates.Length==1)return Directory.GetParent(candidates[0]).FullName;if(candidates.Length>1)throw new Exception("检测到不同路径的多个 PSD Lingo。请保留一个需要更新的版本运行，关闭其他版本后重新打开本更新程序。");
 using(var key=Registry.CurrentUser.OpenSubKey(@"Software\PSD Lingo")){string saved=key==null?null:key.GetValue("InstallRoot") as string;if(saved!=null&&ValidRuntime(Path.Combine(saved,"runtime")))return Full(saved);}
 return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","PSD Lingo");}
 byte[] Payload(){string self=Application.ExecutablePath;using(var f=File.OpenRead(self)){if(f.Length<48)throw new Exception("安装文件损坏");f.Position=f.Length-48;var r=new BinaryReader(f);if(Encoding.ASCII.GetString(r.ReadBytes(8))!="PLSETUP1")throw new Exception("安装文件缺少载荷");long length=r.ReadInt64();byte[] expected=r.ReadBytes(32);if(length<=0||length>512L*1024*1024||length>f.Length-48)throw new Exception("安装载荷大小无效");f.Position=f.Length-48-length;byte[] bytes=r.ReadBytes((int)length);using(var sha=SHA256.Create()){if(!sha.ComputeHash(bytes).SequenceEqual(expected))throw new Exception("安装文件校验失败，请重新下载");}return bytes;}}
 void Extract(byte[] bytes,string stage){Directory.CreateDirectory(stage);using(var stream=new MemoryStream(bytes))using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){long total=0,completed=0,expected=zip.Entries.Sum(item=>item.Length);foreach(var e in zip.Entries){string name=e.FullName.Replace('/',Path.DirectorySeparatorChar);if(name.Contains(":")||Path.IsPathRooted(name)||name.Split(Path.DirectorySeparatorChar).Contains(".."))throw new Exception("安装载荷路径无效");string dest=Full(Path.Combine(stage,name));if(!Under(dest,stage))throw new Exception("安装载荷越界");total+=e.Length;if(total>2L*1024*1024*1024)throw new Exception("安装载荷过大");if(e.Name.Length==0){Directory.CreateDirectory(dest);continue;}Directory.CreateDirectory(Path.GetDirectoryName(dest));using(var input=e.Open())using(var output=File.Create(dest)){byte[] buffer=new byte[1024*1024];int read;while((read=input.Read(buffer,0,buffer.Length))>0){output.Write(buffer,0,read);completed+=read;ExtractProgress(completed,expected);}}}}if(!ValidRuntime(stage))throw new Exception("安装载荷不是有效的 PSD Lingo 程序");}
 static Process Launch(string exe,string arguments){return Process.Start(new ProcessStartInfo(exe,arguments){WorkingDirectory=Path.GetDirectoryName(exe),UseShellExecute=false,CreateNoWindow=true});}
 static bool Acknowledged(string file,string nonce){try{return File.Exists(file)&&File.ReadAllText(file)==nonce;}catch(IOException){return false;}}
 static void Move(string from,string to){for(int i=0;;i++){try{Directory.Move(from,to);return;}catch(IOException){if(i>=99)throw;Thread.Sleep(100);}}}
 void Install(){Progress("校验完整安装包…");byte[] payload=Payload();string root=Full(Target()),runtime=Path.Combine(root,"runtime"),exe=Path.Combine(runtime,"PSD Lingo.exe");if(Under(Application.ExecutablePath,runtime))throw new Exception("请将更新 EXE 移到程序 runtime 文件夹之外后再运行，例如下载目录。");Directory.CreateDirectory(root);string stage=Path.Combine(root,".psd-lingo-stage-"+Guid.NewGuid().ToString("N")),backup=Path.Combine(root,"runtime.previous-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));bool moved=false,swapped=false;Process child=null;string resultFile=Environment.GetEnvironmentVariable("PSD_LINGO_SETUP_RESULT");
 using(var mutex=new Mutex(false,@"Local\PSD-Lingo-Setup-"+Convert.ToBase64String(SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(root.ToLowerInvariant()))).Replace('/','_').Replace('+','_'))){if(!mutex.WaitOne(0))throw new Exception("此路径已有一个安装更新任务正在运行");try{
 if(Directory.Exists(runtime)&&!ValidRuntime(runtime))throw new Exception("目标 runtime 不属于 PSD Lingo，已停止，未覆盖任何文件");bool firstInstall=!Directory.Exists(runtime);Progress("正在准备新版文件…\n"+root);Extract(payload,stage);
 if(!firstInstall){int comparison=CompareVersion(RuntimeVersion(stage),RuntimeVersion(runtime));if(comparison<=0){Progress(comparison==0?"当前路径已安装此版本，无需重复更新。":"当前路径已有更新版本，未安装旧版本。");if(resultFile!=null)File.WriteAllText(resultFile,json.Serialize(new{status=comparison==0?"already-current":"newer-installed",root=root}));return;}}
 var processes=RunningAt(exe);if(processes.Count>0){Progress("正在关闭旧版本。请允许正在进行的任务结束…\n"+root);foreach(var p in processes)try{if(p.MainWindowHandle!=IntPtr.Zero)p.CloseMainWindow();}catch{}var until=DateTime.UtcNow.AddSeconds(60);while(RunningAt(exe).Count>0){if(DateTime.UtcNow>until)throw new Exception("旧程序尚未退出，未替换任何文件。请保存工作并关闭旧程序后重新运行更新 EXE。");Thread.Sleep(200);}}
 Progress("在原路径替换程序，保留旧版备份…\n"+root);if(Directory.Exists(runtime)){Move(runtime,backup);moved=true;}Move(stage,runtime);swapped=true;
 string nonce=Guid.NewGuid().ToString("N")+Guid.NewGuid().ToString("N").Substring(0,16),ackDir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"PSD Lingo","updates");Directory.CreateDirectory(ackDir);string ack=Path.Combine(ackDir,"ack-"+nonce);Progress("正在启动并验证新版…");child=Launch(exe,"--update-ack=\""+ack+"\" --update-nonce="+nonce);bool ready=false;for(int i=0;i<600;i++){Thread.Sleep(100);if(Acknowledged(ack,nonce)){ready=true;break;}if(child.HasExited)break;}if(!ready)throw new Exception("新版启动确认失败，正在恢复原版本");File.Delete(ack);
 if(!args.Contains("--no-registration"))using(var key=Registry.CurrentUser.CreateSubKey(@"Software\PSD Lingo")){key.SetValue("InstallRoot",root);key.SetValue("Version",json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(runtime,"resources","app","package.json")))["version"]);}
 string launch=Path.Combine(root,"启动 PSD Lingo.cmd");if(!File.Exists(launch))File.WriteAllText(launch,"@echo off\r\nstart \"\" \"%~dp0runtime\\PSD Lingo.exe\"\r\n",Encoding.ASCII);
 if(firstInstall&&!args.Contains("--no-shortcut")&&!HasDesktopShortcut()){string desktop=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);File.WriteAllText(Path.Combine(desktop,"灵搭 Sparkit.url"),"[InternetShortcut]\r\nURL="+new Uri(exe).AbsoluteUri+"\r\nIconFile="+exe+"\r\nIconIndex=0\r\n",Encoding.Unicode);}
 if(resultFile!=null)File.WriteAllText(resultFile,json.Serialize(new{status="success",root=root,backup=moved?backup:null}));
 }catch(Exception error){if(child!=null)try{if(!child.HasExited){child.Kill();child.WaitForExit();}}catch{}if(swapped&&Directory.Exists(runtime))Move(runtime,Path.Combine(root,"runtime.failed-"+Guid.NewGuid().ToString("N")));if(moved&&Directory.Exists(backup)&&!Directory.Exists(runtime))Move(backup,runtime);if(moved&&File.Exists(exe))Launch(exe,"");if(resultFile!=null)File.WriteAllText(resultFile,json.Serialize(new{status="failed",error=error.Message}));throw;}finally{mutex.ReleaseMutex();if(Directory.Exists(stage))Directory.Delete(stage,true);}}
 }
 [STAThread]static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new Setup(args));}
}
